                if j > start and lines[j].startswith('def ') and not lines[j].startswith(f'def {name}('):
                    end = min(end, j)
                    break
                if lines[j].startswith('class '):
                    end = min(end, j)
                    break
        print(f'--- {name}')
        print('\\n'.join(lines[start:end]))
        print()
